<?php
/** TEMP PS S1676 run v — gavimo-perrusiavimas v1.1 DEPLOY (D) + registro testas (T). */
add_action('init', function(){
  if (!isset($_GET['ps_s1676v'])) return; global $wpdb; $p=$wpdb->prefix; $F=$_GET['ps_s1676v']; $o=array('v'=>'S1676 v','faze'=>$F);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $f=WPMU_PLUGIN_DIR.'/petshop-gavimo-perrusiavimas.php';
  if($F==='D'){ $k=base64_decode(''); if(md5($k)!=='cb01ed0e1d7e0f8290b6fcdfd26d48cc'||@token_get_all($k,TOKEN_PARSE)===false){ $o['STOP']=1; } else { copy($f,$f.'.bak_v10'); file_put_contents($f,$k); $o['md5']=md5_file($f); $r=wp_remote_get(home_url('/?ps_ping_s1676v='.time()),array('timeout'=>25,'sslverify'=>false)); $c=is_wp_error($r)?'ERR':wp_remote_retrieve_response_code($r); $o['ping']=$c; if(is_wp_error($r)||$c>=500){ copy($f.'.bak_v10',$f); $o['ROLLBACK']=1; } } }
  if($F==='T'){
    $pid=17707; $t=$p.'ps_sources';
    $pries=$wpdb->get_row($wpdb->prepare("SELECT id,is_active,updated_at FROM $t WHERE product_id=%d AND source='av'",$pid),ARRAY_A);
    // hook testas: 10 → 11 → 10 (grynas meta, be partijų)
    update_post_meta($pid,'_own_stock_qty',11); $vid=$wpdb->get_row($wpdb->prepare("SELECT updated_at FROM $t WHERE product_id=%d AND source='av'",$pid),ARRAY_A);
    update_post_meta($pid,'_own_stock_qty',10); $po=$wpdb->get_row($wpdb->prepare("SELECT id,is_active,updated_at FROM $t WHERE product_id=%d AND source='av'",$pid),ARRAY_A);
    $o['t17707']=array('pries'=>$pries,'po11'=>$vid,'po10'=>$po,'own_dabar'=>get_post_meta($pid,'_own_stock_qty',true),'hook'=>has_action('updated_post_meta',array('Petshop_Gavimo_Perrusiavimas','meta_own')));
    // prekė be av eilutės su tiekėjo sandėliu — kandidatas realiam scenarijui (tik sąrašas)
    $o['be_av_eiles_su_own']=$wpdb->get_results("SELECT pm.post_id pid, pm.meta_value own FROM {$p}postmeta pm WHERE pm.meta_key='_own_stock_qty' AND pm.meta_value+0>0 AND NOT EXISTS (SELECT 1 FROM $t s WHERE s.product_id=pm.post_id AND s.source='av' AND s.is_active=1) LIMIT 10",ARRAY_A);
  }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT|JSON_PARTIAL_OUTPUT_ON_ERROR); exit;
});
